def solve(inputs: dict) -> float:
    # Xorshift PRNG with specific shifts
    X = inputs.get('X', 68951519)
    shifts = inputs.get('shifts', [13, 9, 17])
    rounds = inputs.get('rounds', 23)
    mask = (1 << 32) - 1  # 32-bit mask

    for _ in range(rounds):
        for shift in shifts:
            if shift > 0:  # left shift
                X ^= (X << shift) & mask
            else:  # right shift
                X ^= (X >> abs(shift)) & mask

    return float(X & mask)

